function findDuplicate(nums) {
  let slow = nums[0];
  let fast = nums[0];

  // phase 1: find a meeting point inside the cycle
  do {
    slow = nums[slow];
    fast = nums[nums[fast]];
  } while (slow !== fast);

  // phase 2: walk one pointer from the start; they meet at the entrance
  slow = nums[0];
  while (slow !== fast) {
    slow = nums[slow];
    fast = nums[fast];
  }
  return slow;
}
